#!/bin/sh
# Called only with a root-owned mkdtemp directory generated by the RPC backend.
set -eu
umask 077
work=$1
case "$work" in /tmp/flowproxy-import.*) ;; *) exit 2 ;; esac
case "${work#/tmp/flowproxy-import.}" in ''|*[!A-Za-z0-9]*) exit 2 ;; esac
exec 8>/var/lock/flowproxy-import.lock
if ! flock -n 8; then
    printf '{"result":false,"error":"Another configuration import is running"}\n'
    exit 1
fi
fail() { printf '{"result":false,"error":"%s"}\n' "$1"; exit 1; }
/usr/bin/ucode /usr/share/flowproxy/config-transfer.uc stage "$work" > "$work/result.json" || { cat "$work/result.json"; exit 1; }
. /usr/share/flowproxy/service_ips.sh
for vendor in apple microsoft; do
    fp_service_validate "$work/service-ips/$vendor.cidr" >/dev/null || fail 'Invalid service IP ranges; configuration unchanged'
done
mkdir "$work/bin"
uci_bin=$(command -v uci)
printf '#!/bin/sh\nexec %s -c %s/config -P %s/delta "$@"\n' "$uci_bin" "$work" "$work" > "$work/bin/uci"
chmod 700 "$work/bin/uci"
if ! PATH="$work/bin:$PATH" FP_SERVICE_CACHE="$work/service-ips" FLOWPROXY_VALIDATE=1 \
    FLOWPROXY_OUTPUT_FILE="$work/rules.nft" FLOWPROXY_WORK_DIR="$work" \
    /usr/share/flowproxy/generate_nft.sh >/dev/null 2>"$work/validation.log" ||
   ! nft -c -f "$work/rules.nft" 2>>"$work/validation.log"; then
    fail 'Rule validation failed; configuration unchanged'
fi
enabled=$("$work/bin/uci" -q get flowproxy.global.enabled || echo 0)
if [ "$enabled" = 1 ]; then
    iface=$("$work/bin/uci" -q get flowproxy.global.interface || echo br-lan)
    ip link show dev "$iface" >/dev/null 2>&1 || fail 'Proxy interface does not exist on this router; configuration unchanged'
fi
/usr/bin/ucode /usr/share/flowproxy/config-transfer.uc export > "$work/backup-result.json" || fail 'Unable to back up existing configuration'
jsonfilter -i "$work/backup-result.json" -e '@.backup' > "$work/previous.json"
cp -p /etc/config/flowproxy "$work/old.config"
cp -p /etc/config/dhcp "$work/old.dhcp"
old_running=0
[ ! -f /var/run/flowproxy.running ] || old_running=1
[ ! -f /tmp/flowproxy/guard-paused ] || cp /tmp/flowproxy/guard-paused "$work/old.paused"
had_cache=0
if [ -d /etc/flowproxy/service-ips ]; then cp -a /etc/flowproxy/service-ips "$work/old.service-ips"; had_cache=1; fi
persistent=/etc/flowproxy/imported/${work##*/}
rollback() {
    trap - EXIT INT TERM
    FLOWPROXY_GUARD_ACTION=1 /etc/init.d/flowproxy stop >/dev/null 2>&1 || true
    cp -p "$work/old.config" /etc/config/flowproxy
    cp -p "$work/old.dhcp" /etc/config/dhcp
    if [ "$had_cache" = 1 ]; then
        cp -a "$work/old.service-ips/." /etc/flowproxy/service-ips/
    else
        rm -f /etc/flowproxy/service-ips/apple.cidr /etc/flowproxy/service-ips/microsoft.cidr
        rm -f /etc/flowproxy/service-ips/apple.json /etc/flowproxy/service-ips/microsoft.json
    fi
    rm -f /tmp/flowproxy/guard-paused
    [ ! -f "$work/old.paused" ] || cp "$work/old.paused" /tmp/flowproxy/guard-paused
    /etc/init.d/dnsmasq restart >/dev/null 2>&1 || true
    if [ "$old_running" = 1 ]; then
        FLOWPROXY_GUARD_ACTION=1 /etc/init.d/flowproxy start >/dev/null 2>&1 || \
            /etc/init.d/flowproxy stop >/dev/null 2>&1 || true
    fi
    rm -rf "$persistent"
    /etc/init.d/flowproxy-guard restart >/dev/null 2>&1 || true
    printf '{"result":false,"error":"Import could not be applied; previous configuration restored"}\n'
}
trap rollback EXIT INT TERM
FLOWPROXY_GUARD_ACTION=1 /etc/init.d/flowproxy stop >/dev/null 2>&1
mkdir -p "$persistent" /etc/flowproxy/service-ips
cp -a "$work/files" "$persistent/files"
for vendor in apple microsoft; do
    cp "$work/service-ips/$vendor.cidr" "/etc/flowproxy/service-ips/$vendor.cidr.next"
    mv "/etc/flowproxy/service-ips/$vendor.cidr.next" "/etc/flowproxy/service-ips/$vendor.cidr"
    printf '{"result":"imported","last_success":0}\n' > "/etc/flowproxy/service-ips/$vendor.json"
done
cp "$work/final/flowproxy" /etc/config/flowproxy.import
chmod 600 /etc/config/flowproxy.import
mv /etc/config/flowproxy.import /etc/config/flowproxy
rm -f /tmp/flowproxy/guard-paused
if [ "$enabled" = 1 ]; then
    FLOWPROXY_GUARD_ACTION=1 /etc/init.d/flowproxy start >/dev/null 2>&1
    test -f /var/run/flowproxy.running
    /etc/init.d/flowproxy enable
fi
cp "$work/previous.json" /etc/flowproxy/last-import-backup.json.next
mv /etc/flowproxy/last-import-backup.json.next /etc/flowproxy/last-import-backup.json
/etc/init.d/flowproxy-guard restart >/dev/null 2>&1
trap - EXIT INT TERM
printf '{"result":true}\n'
